/**
 * Configuration module — reads all settings from environment variables.
 */

export interface AppConfig {
  /** Path to keys.json (user-provided API keys) */
  keysPath: string;
  /** Path to pool-config.json (generated by sync) */
  poolConfigPath: string;
  /** URL of the catalog JSON */
  catalogUrl: string;
  /** Path to pool state file (cooldowns, counters) */
  poolStatePath: string;
  /** Log level: debug | info | warn | error */
  logLevel: string;
  /** HTTP server port for the runtime */
  port: number;
  /** Polling interval for hot-reload (ms) */
  hotReloadIntervalMs: number;
}

export function loadConfig(): AppConfig {
  return {
    keysPath: process.env.KEYS_PATH || './keys.json',
    poolConfigPath: process.env.POOL_CONFIG_PATH || './pool-config.json',
    catalogUrl: process.env.CATALOG_URL || 'https://raw.githubusercontent.com/mnfst/awesome-free-llm-apis/main/data.json',
    poolStatePath: process.env.POOL_STATE_PATH || './llm-pool-state.json',
    logLevel: process.env.LOG_LEVEL || 'info',
    port: parseInt(process.env.PORT || '3001', 10),
    hotReloadIntervalMs: parseInt(process.env.HOT_RELOAD_INTERVAL_MS || '5000', 10),
  };
}
